const createInfiniteParams = <K extends Pick<QueryKey<Options>[0], 'body' | 'headers' | 'path' | 'query'>>(queryKey: QueryKey<Options>, page: K) => {
    const params = { ...queryKey[0] };
    if (page.body) {
        params.body = {
            ...queryKey[0].body as any,
            ...page.body as any
        };
    }
    if (page.headers) {
        params.headers = {
            ...queryKey[0].headers,
            ...page.headers
        };
    }
    if (page.path) {
        params.path = {
            ...queryKey[0].path as any,
            ...page.path as any
        };
    }
    if (page.query) {
        params.query = {
            ...queryKey[0].query as any,
            ...page.query as any
        };
    }
    return params as unknown as typeof page;
};

export const getYcsAdminVideosInfiniteQueryKey = (options?: Options<GetYcsAdminVideosData>): QueryKey<Options<GetYcsAdminVideosData>> => createQueryKey('getYcsAdminVideos', options, true);

/**
 * List Videos
 *
 * Library rows — joins ES metadata, transcript presence, and Neo4j Document presence per video.
 * Channel/`q` filters run in ES; `status`+`lang` are post-filtered in Python (cross-store).
 */
export const getYcsAdminVideosInfiniteOptions = (options?: Options<GetYcsAdminVideosData>) => {
    const opts = infiniteQueryOptions<GetYcsAdminVideosResponse, GetYcsAdminVideosError, InfiniteData<GetYcsAdminVideosResponse>, QueryKey<Options<GetYcsAdminVideosData>>, number | Pick<QueryKey<Options<GetYcsAdminVideosData>>[0], 'body' | 'headers' | 'path' | 'query'>>(
    // @ts-ignore
    {
        queryFn: async ({ pageParam, queryKey, signal }) => {
            // @ts-ignore
            const page: Pick<QueryKey<Options<GetYcsAdminVideosData>>[0], 'body' | 'headers' | 'path' | 'query'> = typeof pageParam === 'object' ? pageParam : {
                query: {
                    offset: pageParam
                }
            };
            const params = createInfiniteParams(queryKey, page);
            const { data } = await getYcsAdminVideos({
                ...options,
                ...params,
                signal,
                throwOnError: true
            });
            return data;
        },
        queryKey: getYcsAdminVideosInfiniteQueryKey(options)
    });
    return opts as Omit<typeof opts, 'initialData'>;
};

